    private static void put(String ar,String en){EN.put(ar,en);}
    static boolean english(Context context){return "en".equals(context.getSharedPreferences(PREFS,Context.MODE_PRIVATE).getString(KEY,"ar"));}
    static String text(Context context,String arabic,String english){return english(context)?english:arabic;}
    static void set(Context context,boolean english){context.getSharedPreferences(PREFS,Context.MODE_PRIVATE).edit().putString(KEY,english?"en":"ar").apply();}
    static void apply(Activity activity){boolean en=english(activity);Locale locale=en?Locale.US:new Locale("ar");Locale.setDefault(locale);Configuration configuration=new Configuration(activity.getResources().getConfiguration());configuration.setLocale(locale);configuration.setLayoutDirection(locale);activity.getResources().updateConfiguration(configuration,activity.getResources().getDisplayMetrics());activity.getWindow().getDecorView().setLayoutDirection(en?android.view.View.LAYOUT_DIRECTION_LTR:android.view.View.LAYOUT_DIRECTION_RTL);}
    static int direction(Context context){return english(context)?View.LAYOUT_DIRECTION_LTR:View.LAYOUT_DIRECTION_RTL;}
    static void watch(Activity activity){if(!english(activity))return;View root=activity.getWindow().getDecorView();translate(root);root.getViewTreeObserver().addOnGlobalLayoutListener(new ViewTreeObserver.OnGlobalLayoutListener(){public void onGlobalLayout(){translate(root);}});}
    private static void translate(View view){if(view instanceof ViewGroup)view.setLayoutDirection(View.LAYOUT_DIRECTION_LTR);if(view instanceof TextView&&!(view instanceof EditText)){TextView text=(TextView)view;CharSequence original=text.getText();String translated=translate(original==null?"":original.toString());if(!translated.equals(original==null?"":original.toString()))text.setText(translated);}if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)translate(group.getChildAt(i));}}
    private static String translate(String value){String direct=EN.get(value);if(direct!=null)return direct;String[][] prefixes={{"مرحبًا بك في ","Welcome to "},{"اليوم  •  ","Today  •  "},{"المتابعة  •  ","Follow-up  •  "},{"الرصيد الحالي  ","Current balance  "},{"الرصيد الافتتاحي: ","Opening balance: "},{"إجمالي ","Total "},{"كشف ","Statement: "},{"العميل: ","Customer: "},{"متابعة: ","Follow-up: "},{"الوقت: ","Time: "},{"صفحة ","Page "}};for(String[] pair:prefixes)if(value.startsWith(pair[0]))return pair[1]+value.substring(pair[0].length());return value;}
